use strict;
use warnings;

# Parse FASTA
my %seqs;
my $current;
open(my $fh, '<', 'sequences.fasta') or die;
while (<$fh>) {
    chomp;
    if (/^>(.+)/) {
        $current = $1;
        $seqs{$current} = '';
    } else {
        $seqs{$current} .= $_;
    }
}
close($fh);

my $input = $seqs{input};
my $output = $seqs{output};
my $len = length($input);

print "Input length: $len\n";
print "Output length: " . length($output) . "\n\n";

# Find the mutation region
my @mutation_regions;
for (my $i = 0; $i < $len; $i++) {
    if (substr($input, $i, 1) ne substr($output, $i, 1)) {
        my $start = $i;
        while ($i < $len && substr($input, $i, 1) ne substr($output, $i, 1)) {
            $i++;
        }
        push @mutation_regions, {start => $start, end => $i};
        print "Mutation region: $start-$i\n";
    }
}

print "\nTotal mutation regions: " . scalar(@mutation_regions) . "\n";
my $first = $mutation_regions[0]{start};
my $last = $mutation_regions[-1]{end};
print "Overall mutation span: $first to $last (" . ($last - $first) . " bp)\n\n";

# Design primers for Q5 SDM - need ~15-25bp on each side of the change
my @primers;

# For circular plasmid, we design forward and reverse primers that span the mutation
# The primers should be complementary and cover the mutation region

for my $region (@mutation_regions) {
    my $mut_start = $region->{start};
    my $mut_end = $region->{end};
    my $mut_len = $mut_end - $mut_start;

    # Design forward primer: ~20bp before mutation + mutation + ~20bp after
    my $fw_start = $mut_start - 20;
    $fw_start = 0 if $fw_start < 0;
    my $fw_end = $mut_end + 20;
    $fw_end = $len if $fw_end > $len;

    my $fw_primer = substr($input, $fw_start, $fw_end - $fw_start);

    # But we need to use the OUTPUT sequence for the mutated part
    # Reconstruct with output sequence
    my $fw_before = substr($input, $fw_start, $mut_start - $fw_start);
    my $fw_mut = substr($output, $mut_start, $mut_end - $mut_start);
    my $fw_after = substr($input, $mut_end, $fw_end - $mut_end);
    $fw_primer = $fw_before . $fw_mut . $fw_after;

    # Reverse primer is reverse complement
    my $rev_primer = reverse_complement($fw_primer);

    push @primers, {
        fw => $fw_primer,
        rev => $rev_primer,
        fw_len => length($fw_primer),
        rev_len => length($rev_primer),
        region => $region
    };

    print "Forward primer (len " . length($fw_primer) . "): $fw_primer\n";
    print "Reverse primer (len " . length($rev_primer) . "): $rev_primer\n\n";
}

sub reverse_complement {
    my ($seq) = @_;
    my %comp = (A => 'T', T => 'A', G => 'C', C => 'G', a => 't', t => 'a', g => 'c', c => 'g');
    my @bases = split //, $seq;
    my @rev = reverse @bases;
    my $rc = join '', map { $comp{$_} } @rev;
    return $rc;
}
