        # Actually, for the annealing part, we need to match INPUT sequence
        # Before mutation: input[start .. 200-1] = output[start .. 200-1]
        # After mutation: input[230..] = output[269..]
        # So the annealing regions that match input are:
        # Left: output[start .. 200-1] (matches input[start..199])
        # Right: output[269..] but we need input equivalent

        # Let me use input for the right anneal region
        my $in_right_start = 200 + 30; # after mutation in input
        my $in_right_seq = substr($output, 200 + 69, $right_anneal); # same in output

        # Primer is: output[start..200-1] + output[200..268] + input[in_right_start..in_right_start+right_anneal-1]
        my $left_part = substr($output, $start, 200 - $start);
        my $mut_part = substr($output, 200, 69);
        my $right_part = substr($output, 200 + 69, $right_anneal);

        my $fw_primer = $left_part . $mut_part . $right_part;

        # For Tm calculation, use ONLY the annealing parts (not the mutation insertion)
        # Annealing region should be: left_anneal bp + right_anneal bp
        my $tm_seq = substr($fw_primer, 0, $left_anneal) . substr($fw_primer, -$right_anneal);

        next if length($tm_seq) != $left_anneal + $right_anneal;

        my $fw_tm = calc_tm($tm_seq);
        next unless defined $fw_tm;
        next if $fw_tm < 58 || $fw_tm > 72;

        my $rev_primer = reverse_complement($fw_primer);
        my $rev_tm_seq = reverse_complement($tm_seq);
        my $rev_tm = calc_tm($rev_tm_seq);
        next unless defined $rev_tm;
        next if $rev_tm < 58 || $rev_tm > 72;

        my $diff = abs($fw_tm - $rev_tm);
        next if $diff > 5;

        push @valid, {
            left=>$left_anneal, right=>$right_anneal,
            fw=>$fw_primer, rev=>$rev_primer,
            fw_tm=>$fw_tm, rev_tm=>$rev_tm, diff=>$diff,
            tm_seq=>$tm_seq
        };
        print "VALID: L=$left_anneal R=$right_anneal TmSeq=" . length($tm_seq) . "bp FwTm=$fw_tm RevTm=$rev_tm Diff=$diff\n";
    }
}

if (@valid) {
    @valid = sort { $a->{diff} <=> $b->{diff} } @valid;
    my $best = $valid[0];

    open(my $out, '>', 'primers.fasta') or die;
    print $out ">primer_1_forward\n";
    print $out $best->{fw} . "\n";
    print $out ">primer_1_reverse\n";
    print $out $best->{rev} . "\n";
    close($out);
    print "\nWrote primers.fasta\n";
} else {
    print "\nNo valid primers found\n";
}
