# Verify reverse is reverse complement of forward
sub reverse_complement {
    my ($seq) = @_;
    my %comp = (A => 'T', T => 'A', G => 'C', C => 'G', a => 't', t => 'a', g => 'c', c => 'g');
    my @bases = split //, $seq;
    my @rev = reverse @bases;
    return join '', map { $comp{$_} // $_ } @rev;
}

my $fw_rc = reverse_complement($fw);
if ($fw_rc eq $rev) {
    print "OK: Reverse is correct reverse complement of forward\n";
} else {
    print "ERROR: Reverse is NOT reverse complement of forward\n";
}

# Calculate Tm of annealing regions
sub calc_tm {
    my ($oligo) = @_;
    my $result = `oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 \Q$oligo\E 2>/dev/null`;
    if ($result =~ /(\d+\.\d+)/) {
        return $1;
    }
    return undef;
}

